vulnerable_code:
app.get('/api/invoices/:invoiceId', async (req, res) => {
  const invoice = await db.Invoice.findOne({ where: { id: req.params.invoiceId } });
  res.json(invoice);
});

corrected_code:
app.get('/api/invoices/:invoiceId', async (req, res) => {
  const invoice = await db.Invoice.findOne({ where: { id: req.params.invoiceId, accountId: req.user.accountId } });
  if (!invoice) return res.status(404).send('Not Found');
  res.json(invoice);
});
